-- database: agile_local
select "activities"."id", "activities"."project_id", "activities"."subproject_id", "activities"."sprint_id", "activities"."release_id", "activities"."user_story_id", "activities"."assignee_id", "activities"."created_by_id", "activities"."title", "activities"."description", "activities"."status", "activities"."priority", "activities"."work_type", "activities"."track", "activities"."percent_complete", "activities"."is_blocked", "activities"."blocked_reason", "activities"."due_date", "activities"."started_at", "activities"."completed_at", "activities"."created_at", "activities"."updated_at", "subprojects"."code", "subprojects"."name", "users"."full_name" from "activities" inner join "projects" on "projects"."id" = "activities"."project_id" left join "subprojects" on "subprojects"."id" = "activities"."subproject_id" left join "users" on "users"."id" = "activities"."assignee_id" where ("projects"."archived_at" is null and "activities"."due_date" is not null and "activities"."assignee_id" = $1 and ("activities"."status" <> $2 or ("activities"."status" = $3 and "activities"."completed_at" >= $4 and "activities"."completed_at" <= $5))) order by "activities"."due_date" asc, "activities"."id" asc limit $6;
